<script setup>
import {useUiText} from "../ui-text";
const ui=useUiText();

import ParameterReset from './ParameterReset.vue';
import PanelReferenceOverlay from './PanelReferenceOverlay.vue';
import ReferenceOverlayControls from './ReferenceOverlayControls.vue';
import {resetProfileParameters,loraDefaults} from '../../shared/parameter-defaults.mjs';

import {ref,computed,watch,nextTick,onMounted,onUnmounted,onActivated} from 'vue';
import {Sparkles,ImagePlus,Upload,FolderOpen,Maximize2,Download,ArrowRight,Plus,X,RotateCcw,Paintbrush,Eraser,Images,ChevronDown,SlidersHorizontal,Shuffle,LoaderCircle} from 'lucide-vue-next';
import {useStudio,api} from '../store';
import PromptField from './PromptField.vue';
import FeatureParams from './FeatureParams.vue';
import {ensurePanelGeneration,panelImage,setPanelImage} from '../../shared/panel-generation.mjs';
import {makeProfile} from '../../server/profiles.mjs';
import {inpaintPresets,applyInpaintPreset} from '../editor/inpaint-presets';
import {importableImages} from '../../shared/image-import.mjs';
const importing=ref(false),dropActive=ref(false);let dragDepth=0;
const props=defineProps({mode:String,embedded:Boolean,panelTarget:Object,panel:Object,page:Object});const s=useStudio();const inp=ref(),maskCanvas=ref(),imageElement=ref(),brush=ref(35),eraser=ref(false),compare=ref(50),showCompare=ref(false),source=ref(null),strokes=ref(0),zoomed=ref(false);let backing,painting=false,lastPoint,history=[],maskSaveTimer;
const p=computed(()=>props.panel?ensurePanelGeneration(props.panel,s.gallery,s.config.activeProfile).params:s.p);
const parameterDefaults=computed(()=>makeProfile(p.value.type));
function restoreGroup(group){resetProfileParameters(p.value,group);s.notify('已恢复默认参数');}
const profileType=computed({get:()=>p.value.type,set:type=>{if(!props.panel){s.config.activeProfile=type;return;}const state=props.panel.generation;state.profiles||={};state.profiles[p.value.type]=JSON.parse(JSON.stringify(p.value));const next=state.profiles[type]||makeProfile(type);state.params={...JSON.parse(JSON.stringify(next)),positive:p.value.positive,negative:p.value.negative};}});
const selectedImage=computed(()=>props.panel?(panelImage(props.panel,s.gallery)|| (props.panel.image?{id:props.panel.imageId,url:props.panel.image,title:props.panel.name,params:p.value}:null)):s.selectedImages[props.mode||'generate']);
const matchesTarget=job=>props.panelTarget?job.target?.projectId===props.panelTarget.projectId&&job.target?.pageId===props.panelTarget.pageId&&job.target?.panelId===props.panelTarget.panelId:!job.target&&!!job.imageId===(props.mode==='inpaint');
const activeJob=computed(()=>s.jobs.find(j=>['running','cancelling'].includes(j.status)&&matchesTarget(j)));
const jobHistory=computed(()=>s.jobs.filter(matchesTarget));
const promptScope=computed(()=>props.panelTarget?'panel:'+props.panelTarget.projectId+':'+props.panelTarget.panelId+':'+p.value.type+':'+props.mode:props.mode||'generate');
watch(()=>props.panel&&(props.mode==='inpaint'?[p.value.inpaint.positive,p.value.inpaint.negative]:[p.value.positive,p.value.negative]),value=>{if(value){props.panel.positive=value[0];props.panel.negative=value[1];}},{immediate:true});
const emit=defineEmits(['queued']);
const previewSize=computed(()=>imageSize.value);
const previewFrame=ref(),previewViewport=ref(),previewArea=ref({w:800,h:430}),imageSize=ref({w:0,h:0});let previewObserver,previewDrag;
const previewKey=computed(()=>props.panelTarget?'panel:'+props.panelTarget.projectId+':'+props.panelTarget.panelId+':'+(props.mode||'generate'):props.mode||'generate');
const previewPrefs=computed(()=>{const all=s.config.previewSizes||(s.config.previewSizes={});return all[previewKey.value]||(all[previewKey.value]={width:null,height:s.config.previewHeight||430,zoom:null});});
const fitScale=computed(()=>previewSize.value.w?Math.min((previewArea.value.w-24)/previewSize.value.w,(previewArea.value.h-24)/previewSize.value.h,1):1);
const imageZoom=computed(()=>previewPrefs.value.zoom??Math.max(10,Math.round(fitScale.value*100)));
const previewImageStyle=computed(()=>previewSize.value.w?{width:previewSize.value.w*imageZoom.value/100+'px',height:previewSize.value.h*imageZoom.value/100+'px'}:{});
onMounted(()=>{previewObserver=new ResizeObserver(entries=>{const r=entries[0].contentRect;if(r.width&&r.height)previewArea.value={w:r.width,h:r.height};});if(previewViewport.value)previewObserver.observe(previewViewport.value);});
onUnmounted(()=>{previewObserver?.disconnect();clearTimeout(maskSaveTimer);});
function imageLoaded(){imageSize.value={w:imageElement.value?.naturalWidth||0,h:imageElement.value?.naturalHeight||0};initializeImage();}
function resizePreview(e){e.preventDefault();e.currentTarget.setPointerCapture(e.pointerId);const r=previewFrame.value.getBoundingClientRect();previewDrag={kind:'resize',x:e.clientX,y:e.clientY,w:r.width,h:r.height};}
function movePreviewResize(e){if(previewDrag?.kind!=='resize')return;previewPrefs.value.width=Math.min(previewFrame.value.parentElement.clientWidth,Math.max(320,previewDrag.w+e.clientX-previewDrag.x));previewPrefs.value.height=Math.max(220,Math.min(1400,previewDrag.h+e.clientY-previewDrag.y));}
async function zoomPreview(value,e){const el=previewViewport.value,img=imageElement.value;if(!img)return;const r=el.getBoundingClientRect(),px=e?.clientX??r.left+el.clientWidth/2,py=e?.clientY??r.top+el.clientHeight/2,old=img.getBoundingClientRect(),x=(px-old.left)/old.width,y=(py-old.top)/old.height;previewPrefs.value.zoom=Math.max(10,Math.min(800,Math.round(value)));await nextTick();const fresh=img.getBoundingClientRect();el.scrollLeft+=fresh.left+x*fresh.width-px;el.scrollTop+=fresh.top+y*fresh.height-py;}
function previewWheel(e){e.preventDefault();zoomPreview(imageZoom.value*Math.exp(-e.deltaY*.0015),e);}
function startPreviewPan(e){if(e.button!==1)return;e.preventDefault();previewViewport.value.setPointerCapture(e.pointerId);previewDrag={kind:'pan',x:e.clientX,y:e.clientY,left:previewViewport.value.scrollLeft,top:previewViewport.value.scrollTop};}
function movePreviewPan(e){if(previewDrag?.kind!=='pan')return;previewViewport.value.scrollLeft=previewDrag.left-e.clientX+previewDrag.x;previewViewport.value.scrollTop=previewDrag.top-e.clientY+previewDrag.y;}
const desktop=!!window.desktop;
const inpaint=computed(()=>props.mode==='inpaint');
const ratios=[{label:'1:1',name:'方形',w:1024,h:1024},{label:'16:9',name:'横屏',w:1344,h:768},{label:'9:16',name:'竖屏',w:768,h:1344},{label:'3:4',name:'肖像',w:896,h:1200},{label:'4:3',name:'风景',w:1200,h:896},{label:'2:3',name:'漫画',w:832,h:1248}];
const displayed=computed(()=>props.panel?((activeJob.value?s.preview:'')||props.panel.image||''):inpaint.value?selectedImage.value?.url:((activeJob.value?s.preview:'')||selectedImage.value?.url));
watch(()=>selectedImage.value?.id,()=>{if(!inpaint.value||(!props.panel&&s.tab!==props.mode))return;if(!selectedImage.value){source.value=null;history=[];strokes.value=0;return;}if(source.value&&selectedImage.value.sourceImageId===source.value.id)showCompare.value=true;else nextTick(restorePreview);});
function loadOriginal(item){if(!props.panel&&item.params?.type&&s.config.profiles[item.params.type])s.config.activeProfile=item.params.type;source.value=item;showCompare.value=false;if(p.value.inpaint.sourceImageId!==item.id){if(item.params?.positive){p.value.inpaint.positive=item.params.positive;p.value.inpaint.negative=item.params.negative||'';}else{p.value.inpaint.positive='';p.value.inpaint.negative='';s.notify(s.t('这张图片没有保存提示词，请先填写需要生成的内容','This image has no saved prompt. Describe the change first.'));}p.value.inpaint.sourceImageId=item.id;}nextTick(resetMask);}
function restorePreview(){const item=selectedImage.value;if(!item)return;const original=item.generationMode==='inpaint'&&s.gallery.find(i=>i.id===item.sourceImageId),remembered=original&&p.value.inpaint.sourceImageId===original.id;loadOriginal(original||item);if(original){showCompare.value=true;if(!remembered&&item.params){p.value.inpaint.positive=item.params.positive||'';p.value.inpaint.negative=item.params.negative||'';}}}
onActivated(()=>{if(!inpaint.value)return;const item=selectedImage.value;if(!item){source.value=null;history=[];strokes.value=0;return;}if(source.value&&item.sourceImageId===source.value.id)showCompare.value=true;else if(source.value?.id!==item.id)nextTick(restorePreview);});
function initializeImage(){if(!props.panel&&s.tab!==props.mode)return;if(inpaint.value&&!showCompare.value){if(!source.value)restorePreview();else if(source.value.id!==selectedImage.value?.id&&selectedImage.value?.sourceImageId!==source.value.id)loadOriginal(selectedImage.value);else resetMask();}}
function paintMode(erase){if(showCompare.value)loadOriginal(selectedImage.value);eraser.value=erase;showCompare.value=false;}
function resetMask(){if(!imageElement.value||!maskCanvas.value)return;const img=imageElement.value,canvas=maskCanvas.value;if(!img.complete||!img.naturalWidth||!img.naturalHeight)return;canvas.width=img.naturalWidth;canvas.height=img.naturalHeight;backing=document.createElement('canvas');backing.width=canvas.width;backing.height=canvas.height;history=[];strokes.value=0;renderMask();const draft=p.value.inpaint.maskDraft;if(draft?.imageId===source.value?.id&&draft.mask){const image=new Image();image.onload=()=>{if(backing.width===image.width&&backing.height===image.height){backing.getContext('2d').drawImage(image,0,0);strokes.value=draft.strokes||1;renderMask();}};image.src=draft.mask;}}
function saveMask(){clearTimeout(maskSaveTimer);if(backing?.width&&backing?.height&&source.value&&p.value.inpaint.sourceImageId===source.value.id)p.value.inpaint.maskDraft={imageId:source.value.id,mask:backing.toDataURL('image/png'),strokes:strokes.value};}
function endPaint(){painting=false;saveMask();}
function clearMask(){if(backing){backing.getContext('2d').clearRect(0,0,backing.width,backing.height);history=[];strokes.value=0;renderMask();saveMask();}}

function renderMask(){if(!maskCanvas.value||!backing)return;const c=maskCanvas.value.getContext('2d');c.clearRect(0,0,maskCanvas.value.width,maskCanvas.value.height);c.drawImage(backing,0,0);c.globalCompositeOperation='source-in';c.fillStyle='rgba(122,92,255,.55)';c.fillRect(0,0,maskCanvas.value.width,maskCanvas.value.height);c.globalCompositeOperation='source-over';}
function point(e){const rect=maskCanvas.value.getBoundingClientRect();return{x:(e.clientX-rect.left)/rect.width*backing.width,y:(e.clientY-rect.top)/rect.height*backing.height};}
function down(e){if(e.button!==0||!backing||showCompare.value)return;painting=true;maskCanvas.value.setPointerCapture(e.pointerId);history.push(backing.getContext('2d').getImageData(0,0,backing.width,backing.height));if(history.length>10)history.shift();lastPoint=point(e);draw(e);strokes.value++;}
function draw(e){if(!painting)return;const current=point(e),ctx=backing.getContext('2d');ctx.globalCompositeOperation=eraser.value?'destination-out':'source-over';ctx.strokeStyle='#ffffff';ctx.lineWidth=brush.value*backing.width/maskCanvas.value.getBoundingClientRect().width;ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();ctx.moveTo(lastPoint.x,lastPoint.y);ctx.lineTo(current.x+0.01,current.y);ctx.stroke();lastPoint=current;renderMask();clearTimeout(maskSaveTimer);maskSaveTimer=setTimeout(saveMask,180);}
function undoMask(){if(history.length){backing.getContext('2d').putImageData(history.pop(),0,0);strokes.value=Math.max(0,strokes.value-1);renderMask();saveMask();}}
function maskData(){const canvas=document.createElement('canvas');canvas.width=backing.width;canvas.height=backing.height;const ctx=canvas.getContext('2d');ctx.fillStyle='black';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(backing,0,0);return canvas.toDataURL('image/png');}
async function generate(){if(inpaint.value){if(!source.value||!strokes.value){s.notify(s.t('请先导入图片，再涂抹需要修改的区域','Import an image and paint the area to edit'),'error');return;}const registered=await s.materializeImage({...source.value,params:p.value,origin:props.panel?.imageOrigin?.mode});const result=await s.generate({imageId:registered.id,mask:maskData(),mode:'inpaint',...(props.panelTarget?{params:p.value,target:props.panelTarget}:{})});if(result)emit('queued',result);}else{const result=await s.generate(props.panelTarget?{target:props.panelTarget,params:p.value}:{});if(result)emit('queued',result);}}
function imported(items){if(!items?.length)return;if(inpaint.value){clearTimeout(maskSaveTimer);painting=false;p.value.inpaint.maskDraft=null;showCompare.value=false;strokes.value=0;history=[];}if(props.panel)chooseImage(items[0]);else if(inpaint.value)nextTick(()=>loadOriginal(items[0]));previewPrefs.value.zoom=null;}
async function importFiles(files){if(importing.value)return;const images=importableImages(files);if(!images.length){s.notify(s.t('请上传 PNG、JPG 或 WebP 图片','Choose a PNG, JPG or WebP image'),'error');return;}importing.value=true;try{await s.action(async()=>{const items=await s.importImages(images,{select:!props.panel,mode:props.mode||'generate'});imported(items);if(items.length>1)s.notify('已导入 '+items.length+' 张图片，正在使用第一张');});}finally{importing.value=false;}}
async function importFile(event){await importFiles(event.target.files);event.target.value='';}
async function importDesktop(){if(importing.value)return;importing.value=true;try{const items=await s.importImages(undefined,{select:!props.panel,mode:props.mode||'generate'});imported(items);}finally{importing.value=false;}}
function openImport(){if(desktop)s.action(importDesktop);else inp.value?.click();}
function dragEnter(event){if(![...(event.dataTransfer?.types||[])].includes('Files'))return;event.preventDefault();dragDepth++;dropActive.value=true;}
function dragLeave(){dragDepth=Math.max(0,dragDepth-1);if(!dragDepth)dropActive.value=false;}
function dragOver(event){if([...(event.dataTransfer?.types||[])].includes('Files')){event.preventDefault();event.dataTransfer.dropEffect='copy';}}
async function dropImages(event){event.preventDefault();event.stopPropagation();dragDepth=0;dropActive.value=false;await importFiles(event.dataTransfer?.files);}
function addLora(){p.value.loras.push({name:s.models.loras?.[0]||'',...loraDefaults(s.models.loras?.[0])});}
function chooseImage(item){if(props.panel)setPanelImage(props.panel,item);else s.selectImage(item,props.mode||'generate');s.galleryPicker=false;nextTick(()=>loadOriginal(item));}
async function exportImage(){if(!selectedImage.value)return;const blob=await (await fetch(selectedImage.value.url)).blob();await s.exportFile((selectedImage.value.title||props.panel?.name||'分镜图片')+'.png',blob);}
function toComic(){if(!s.project)s.newProject();else s.tab='comic';}
</script>
<template><div class="generation-workspace">

 <section class="card preview-card" @dragenter="dragEnter" @dragleave="dragLeave" @dragover="dragOver" @drop="dropImages"><div class="card-heading generation-preview-header"><div><span class="dot lavender"/><strong>{{ui(inpaint?s.t('画笔重绘工作区','Inpaint workspace'):s.t('图像预览','Image preview'))}}</strong><span class="muted">{{ui(activeJob?activeJob.stage:s.t('原始图像与生成结果','Source and generated image'))}}</span></div><div class="button-row"><button class="secondary" :disabled="importing" @click="openImport"><Upload :size="16"/>{{ui(importing?s.t('正在导入…','Importing…'):s.t('上传图片','Upload image'))}}</button><button class="quiet" @click="s.galleryPicker=true"><Images :size="16"/>{{ui(s.t('从画廊选择','Choose from gallery'))}}</button><ReferenceOverlayControls v-if="panel&&page"/><button v-if="selectedImage" class="icon-button" @click="zoomed=true" :title="ui(s.t('查看大图','Full image'))"><Maximize2 :size="17"/></button><button class="quiet" @click="s.openFolder('output')"><FolderOpen :size="16"/>{{ui(s.t('本地文件夹','Local folder'))}}</button></div></div>
  <div ref="previewFrame" class="preview-stage adjustable-preview" :style="{height:previewPrefs.height+'px',width:previewPrefs.width?previewPrefs.width+'px':'100%'}"><div v-if="dropActive" class="image-drop-overlay"><Upload :size="32"/><strong>{{ui(s.t('松开以导入图片','Drop to import image'))}}</strong><span>PNG · JPG · WebP</span></div><div ref="previewViewport" class="preview-viewport" @wheel="previewWheel" @pointerdown="startPreviewPan" @pointermove="movePreviewPan" @pointerup="previewDrag=null" @pointercancel="previewDrag=null"><div class="preview-content" :style="displayed?{width:(previewSize.w*imageZoom/100+24)+'px',height:(previewSize.h*imageZoom/100+24)+'px'}:{}"><div v-if="displayed" class="image-holder" :style="previewImageStyle"><img ref="imageElement" :src="displayed" @load="imageLoaded" :alt="ui(s.t('创作预览','Image preview'))"/><PanelReferenceOverlay v-if="panel&&page&&s.config.previewReference?.enabled!==false" :page="page" :panel="panel" :width="imageSize.w" :height="imageSize.h" :opacity="s.config.previewReference?.opacity??.35"/><template v-if="inpaint"><img v-if="showCompare&&source" :src="source.url" class="compare-image" :style="{clipPath:`inset(0 ${100-compare}% 0 0)`}"/><canvas v-show="!showCompare" ref="maskCanvas" v-brush-cursor="{size:brush,enabled:!showCompare}" class="mask-overlay" @pointerdown="down" @pointermove="draw" @pointerup="endPaint" @pointercancel="endPaint"/><div v-if="showCompare" class="compare-line" :style="{left:compare+'%'}"><span>↔</span></div></template></div><div v-else class="preview-empty"><div class="empty-art"><div class="art-frame"><ImagePlus :size="44"/><span/><i/></div><div class="art-star"><Sparkles :size="20"/></div></div><h3>{{ui(inpaint?s.t('把想修改的图片放在这里','Add an image to edit'):s.t('你的下一幅故事，从这里开始','Your next story starts here'))}}</h3><p>{{ui(inpaint?s.t('点击上传或直接拖入图片，用画笔涂抹区域，再描述希望出现的内容。','Upload or drop an image, paint a region, and describe the change.'):s.t('写下场景、选择尺寸，点击下方按钮即可生成。','Describe a scene, choose a size, and generate below.'))}}</p><div class="button-row" v-if="inpaint"><button class="secondary" @click="desktop?s.action(importDesktop):inp.click()"><Upload :size="15"/>{{ui(s.t('导入图片','Import image'))}}</button><button class="secondary" @click="s.galleryPicker=true"><Images :size="15"/>{{ui(s.t('从画廊选择','Choose from gallery'))}}</button></div><span v-else class="preview-tip">{{ui(s.t('本地模型生成 · 无需账号 · 自动保存','Local generation · No account · Auto save'))}}</span></div>
  </div></div><button class="preview-resize-grip" :aria-label="ui(&quot;拖动调整预览区宽度和高度&quot;)" :title="ui(&quot;拖动调整预览区宽度和高度&quot;)" @pointerdown="resizePreview" @pointermove="movePreviewResize" @pointerup="previewDrag=null" @pointercancel="previewDrag=null"><svg width="20" height="20"><path d="M5 17L17 5M11 17L17 11" stroke="currentColor" stroke-width="2"/></svg></button><div v-if="activeJob" class="preview-running"><LoaderCircle :size="15" class="spin"/>{{ui(activeJob.stage)}} · {{ui(activeJob.progress)}}%</div>
  </div><div class="preview-bottom"><span>{{ui(selectedImage?selectedImage.title:s.t('预览区可调节大小','Resizable preview area'))}}</span><div class="preview-zoom-tools"><button class="quiet" @click="previewPrefs.zoom=null">{{ui("适合窗口")}}</button><button class="icon-button" :aria-label="ui(&quot;缩小预览画面&quot;)" @click="zoomPreview(imageZoom/1.2)">−</button><span>{{ui(imageZoom)}}%</span><button class="icon-button" :aria-label="ui(&quot;放大预览画面&quot;)" @click="zoomPreview(imageZoom*1.2)">＋</button></div><label>{{ui(s.t('预览高度','Height'))}}<input type="range" v-model.number="previewPrefs.height" min="220" max="1200" step="1"/></label><button v-if="selectedImage" class="quiet" @click="exportImage"><Download :size="15"/>{{ui(s.t('保存图片','Save image'))}}</button></div>
  <div v-if="inpaint&&displayed" class="mask-toolbar"><button :class="['secondary',{selected:!eraser&&!showCompare}]" @click="paintMode(false)"><Paintbrush :size="15"/>{{ui(s.t('涂抹区域','Paint'))}}</button><button :class="['secondary',{selected:eraser&&!showCompare}]" @click="paintMode(true)"><Eraser :size="15"/>{{ui(s.t('橡皮擦','Erase'))}}</button><label>{{ui(s.t('画笔大小','Brush'))}} <input type="range" v-model.number="brush" min="5" max="120"/>{{ui(brush)}} px</label><button class="quiet" @click="undoMask"><RotateCcw :size="15"/>{{ui(s.t('撤销','Undo'))}}</button><button class="quiet" @click="clearMask">{{ui(s.t('清空遮罩','Clear mask'))}}</button><button v-if="source&&selectedImage?.jobId" class="secondary" @click="showCompare=!showCompare">{{ui(s.t('前后对比','Compare'))}}</button><input v-if="showCompare" type="range" v-model.number="compare" min="0" max="100" step="0.1"/></div>
 </section>
 <section v-if="inpaint" class="card inpaint-prompt-top"><div class="info-note">{{ui(s.t('① 导入原图 → ② 修改原图提示词并涂抹 → ③ 一键生成。紫色区域会被修改，其余保留。','1. Import image → 2. Edit prompt and paint → 3. Generate. Only painted areas change.'))}}</div><PromptField :scope="promptScope" v-model="p.inpaint.positive"/><PromptField :scope="promptScope" v-model="p.inpaint.negative" negative/></section>
 <div class="generation-actions"><div><div class="batch-control"><label><span>{{ui(s.t('连续生成','Images'))}}</span><input type="number" :aria-label="ui(&quot;连续生成张数&quot;)" v-model.number="p.batch" min="1" max="50"/><span>{{ui(s.t('张',''))}}</span></label><ParameterReset :model="p" :defaults="parameterDefaults" path="batch" :label="ui(&quot;连续生成张数&quot;)"/></div><span class="muted">{{ui(s.t('逐张生成并保存，生成期间可以切换页面','Images are generated and saved one at a time'))}}</span></div><div class="button-row"><button v-if="selectedImage&&!inpaint&&!embedded" class="secondary" @click="toComic">{{ui(s.t('去制作漫画','Make a comic'))}}<ArrowRight :size="16"/></button><button class="primary generate-button" @click="generate" :disabled="s.engine.state==='starting'"><Sparkles :size="19"/>{{ui(inpaint?s.t('重绘涂抹区域','Inpaint selected area'):s.t('生成图像','Generate image'))}}<span>↵</span></button></div></div>
 <section class="card parameters"><div class="card-heading"><div><SlidersHorizontal :size="17"/><strong>{{ui(s.t('创作参数','Creation settings'))}}</strong><span class="muted">{{ui(s.t('自动保存，不怕关闭软件','Saved automatically'))}}</span></div><button class="quiet" @click="restoreGroup('all')"><RotateCcw :size="14"/>{{ui("恢复本页默认参数")}}</button><span class="badge subtle">{{ui(p.type==='expanded'?'2.9B':'Original')}}</span></div><div class="parameter-content"><div class="model-row"><div><label>{{ui(s.t('模型类型','Model type'))}}</label><div class="segmented"><button :class="{active:profileType==='original'}" @click="profileType='original'">Anima {{ui(s.t('原版','Original'))}}</button><button :class="{active:profileType==='expanded'}" @click="profileType='expanded'">Anima 2.9B</button></div></div><label class="model-file">{{ui(s.t('本地模型文件','Model file'))}}<select v-model="p.model"><option :value="p.model">{{ui(p.model)}}{{ui(!s.models.diffusion_models?.includes(p.model)?s.t('（尚未安装）',' (not installed)'):'')}}</option><option v-for="m in s.models.diffusion_models?.filter(m=>m!==p.model)" :value="m">{{ui(m)}}</option></select></label><button class="icon-button" @click="s.openFolder('diffusion_models')" :title="ui(s.t('打开模型目录','Open model folder'))"><FolderOpen :size="18"/></button></div>
  <template v-if="!inpaint"><PromptField :scope="promptScope" v-model="p.positive"/><PromptField :scope="promptScope" v-model="p.negative" negative/></template>
  <div class="dimensions"><div class="field-title"><label>{{ui(s.t('图像尺寸','Image size'))}}</label><span>{{ui(s.t('第一次使用推荐 1:1；更大尺寸需要更多显存','Start at 1:1. Larger images need more VRAM.'))}}</span></div><div class="ratio-row"><button v-for="r in ratios" :class="['ratio-button',{active:p.width===r.w&&p.height===r.h}]" @click="p.width=r.w;p.height=r.h"><i :style="{width:(r.w>r.h?23:16)+'px',height:(r.h>r.w?23:16)+'px'}"/><strong>{{ui(r.label)}}</strong><small>{{ui(s.t(r.name,r.label))}}</small></button><div class="custom-dimensions"><div class="resettable-field" ><label><span class="parameter-caption">{{ui(s.t('宽度','Width'))}}</span><input type="number" v-model.number="p.width" min="256" max="4096" step="16" data-wheel-step="32" data-wheel-integer/></label><ParameterReset :model="p" :defaults="parameterDefaults" path="width"/></div><span>×</span><div class="resettable-field" ><label><span class="parameter-caption">{{ui(s.t('高度','Height'))}}</span><input type="number" v-model.number="p.height" min="256" max="4096" step="16" data-wheel-step="32" data-wheel-integer/></label><ParameterReset :model="p" :defaults="parameterDefaults" path="height"/></div><span>px</span></div></div></div>
  <details class="advanced"><summary><SlidersHorizontal :size="16"/>{{ui(s.t('高级生成参数与可选 LoRA','Advanced settings & optional LoRAs'))}}<span>{{ui(s.t('想进一步调整画风时再展开','Open when you want more control'))}}</span><ChevronDown :size="16"/></summary><div class="advanced-content"><div class="button-row"><button class="quiet" @click="restoreGroup('basic')"><RotateCcw :size="13"/>{{ui("恢复生成默认参数")}}</button></div><div class="lora-title"><strong>{{ui(s.t('LoRA 画风 / 角色（可选）','LoRA style / character (optional)'))}}</strong><button class="quiet" @click="addLora"><Plus :size="15"/>{{ui(s.t('添加 LoRA','Add LoRA'))}}</button><button class="icon-button" @click="s.openFolder('loras')"><FolderOpen :size="16"/></button></div><p v-if="!p.loras.length" class="muted">{{ui(s.t('当前没有加载 LoRA。可以直接使用原模型生成。','No LoRAs loaded. You can generate with the base model.'))}}</p><div v-for="(lora,i) in p.loras" class="lora-row"><input type="checkbox" v-model="lora.enabled"/><select v-model="lora.name"><option value="">{{ui(s.t('请选择兼容当前模型的 LoRA','Choose a compatible LoRA'))}}</option><option v-for="m in s.models.loras" :value="m">{{ui(m)}}</option></select><div class="resettable-field" ><label><span class="parameter-caption">{{ui(s.t('模型权重','Model weight'))}}</span><input type="number" v-model.number="lora.strength_model" min="-3" max="3" step="0.01" data-wheel-step="0.01"/></label><ParameterReset :model="lora" :defaults="loraDefaults(lora.name)" path="strength_model"/></div><div class="resettable-field" ><label><span class="parameter-caption">{{ui(s.t('文本权重','Text weight'))}}</span><input type="number" v-model.number="lora.strength_clip" min="-3" max="3" step="0.01" data-wheel-step="0.01"/></label><ParameterReset :model="lora" :defaults="loraDefaults(lora.name)" path="strength_clip"/></div><button class="icon-button" @click="p.loras.splice(i,1)"><X :size="16"/></button></div>
   <div class="parameter-grid"><div class="resettable-field" ><label><span class="parameter-caption">{{ui(s.t('采样步数','Steps'))}}</span><input type="number" v-model.number="p.steps" data-wheel-integer min="1" max="150"/><small>{{ui(s.t('越多越细致，也越慢','More steps take longer'))}}</small></label><ParameterReset :model="p" :defaults="parameterDefaults" path="steps"/></div><div class="resettable-field" ><label><span class="parameter-caption">{{ui(s.t('提示词强度 CFG','Prompt strength (CFG)'))}}</span><input type="number" v-model.number="p.cfg" min="0" max="30" step="0.1"/></label><ParameterReset :model="p" :defaults="parameterDefaults" path="cfg"/></div><div class="resettable-field" ><label><span class="parameter-caption">{{ui(s.t('采样器','Sampler'))}}</span><select v-model="p.sampler"><option v-for="name in s.models.samplers" :value="name">{{ui(name)}}</option></select></label><ParameterReset :model="p" :defaults="parameterDefaults" path="sampler"/></div><div class="resettable-field" ><label><span class="parameter-caption">{{ui(s.t('调度器','Scheduler'))}}</span><select v-model="p.scheduler"><option v-for="name in s.models.schedulers" :value="name">{{ui(name)}}</option></select></label><ParameterReset :model="p" :defaults="parameterDefaults" path="scheduler"/></div><div class="resettable-field" ><label><span class="parameter-caption">{{ui(s.t('种子（留空随机）','Seed (empty = random)'))}}</span><input data-wheel-number data-wheel-min="0" data-wheel-max="9007199254740991" inputmode="numeric" v-model="p.seed" :placeholder="ui(s.t('每张自动随机','Random for each image'))"/></label><ParameterReset :model="p" :defaults="parameterDefaults" path="seed"/></div><div class="resettable-field" ><label><span class="parameter-caption">{{ui(s.t('采样偏移 Shift','Sampling shift'))}}</span><input type="number" v-model.number="p.shift" min="0.1" max="20" step="0.1"/></label><ParameterReset :model="p" :defaults="parameterDefaults" path="shift"/></div><label>{{ui(s.t('文本编码器','Text encoder'))}}<select v-model="p.textEncoder"><option :value="p.textEncoder">{{p.textEncoder}}</option><option v-for="m in s.models.text_encoders" :value="m">{{ui(m)}}</option></select></label><label>VAE<select v-model="p.vae"><option :value="p.vae">{{ui(p.vae)}}</option><option v-for="m in s.models.vae" :value="m">{{ui(m)}}</option></select></label><div class="resettable-field" ><label class="checkbox"><span class="parameter-caption">{{ui(s.t('分块 VAE 解码（节省显存）','Tiled VAE decoding'))}}</span><input type="checkbox" v-model="p.tiledDecode"/></label><ParameterReset :model="p" :defaults="parameterDefaults" path="tiledDecode"/></div></div>
  </div></details>
  <section v-if="inpaint" class="inpaint-quick-presets"><strong>{{ui("选好要改的内容，参数自动适配")}}</strong><div class="button-row"><button v-for="preset in inpaintPresets" :key="preset.id" class="secondary" :class="{selected:p.inpaint.preset===preset.id}" @click="p.inpaint=applyInpaintPreset(p,preset.id)">{{ui(preset.name)}}</button></div><p class="muted">{{ui(inpaintPresets.find(preset=>preset.id===p.inpaint.preset)?.tip||'先涂抹要修改的位置，再选择上方模式。未涂抹区域使用原图像素合成保留。')}}</p></section><details v-if="inpaint" class="advanced"><summary><Paintbrush :size="16"/>{{ui(s.t('局部重绘参数','Inpaint settings'))}}<ChevronDown :size="16"/></summary><div class="advanced-content"><button class="quiet" @click="restoreGroup('inpaint')"><RotateCcw :size="13"/>{{ui("恢复重绘默认参数")}}</button><div class="parameter-grid"><div class="resettable-field" ><label><span class="parameter-caption">{{ui(s.t('重绘步数','Inpaint steps'))}}</span><input type="number" v-model.number="p.inpaint.steps" data-wheel-integer min="1" max="150"/></label><ParameterReset :model="p" :defaults="parameterDefaults" path="inpaint.steps"/></div><div class="resettable-field" ><label><span class="parameter-caption">CFG</span><input type="number" v-model.number="p.inpaint.cfg" min="0" max="30" step="0.1"/></label><ParameterReset :model="p" :defaults="parameterDefaults" path="inpaint.cfg"/></div><div class="resettable-field" ><label><span class="parameter-caption">{{ui(s.t('重绘采样器','Inpaint sampler'))}}</span><select v-model="p.inpaint.sampler"><option v-for="v in s.models.samplers" :value="v">{{ui(v)}}</option></select></label><ParameterReset :model="p" :defaults="parameterDefaults" path="inpaint.sampler"/></div><div class="resettable-field" ><label><span class="parameter-caption">{{ui(s.t('重绘调度器','Inpaint scheduler'))}}</span><select v-model="p.inpaint.scheduler"><option v-for="v in s.models.schedulers" :value="v">{{ui(v)}}</option></select></label><ParameterReset :model="p" :defaults="parameterDefaults" path="inpaint.scheduler"/></div><div class="resettable-field" ><label><span class="parameter-caption">{{ui(s.t('蒙版边缘模糊','Mask blur'))}}</span><input type="number" v-model.number="p.inpaint.maskBlur" min="0" max="64"/></label><ParameterReset :model="p" :defaults="parameterDefaults" path="inpaint.maskBlur"/></div><div class="resettable-field" ><label><span class="parameter-caption">{{ui(s.t('重绘区域','Inpaint area'))}}</span><select v-model="p.inpaint.onlyMasked"><option :value="false">{{ui(s.t('原图编码 + 遮罩（官方示例）','Full image + mask (publisher example)'))}}</option><option :value="true">{{ui(s.t('仅蒙版区域（裁切放大）','Masked region only (crop)'))}}</option></select></label><ParameterReset :model="p" :defaults="parameterDefaults" path="inpaint.onlyMasked"/></div><div class="resettable-field" ><label><span class="parameter-caption">{{ui(s.t('裁切区域扩边','Crop padding'))}}</span><input type="number" v-model.number="p.inpaint.padding" min="0" max="512"/></label><ParameterReset :model="p" :defaults="parameterDefaults" path="inpaint.padding"/></div><div class="resettable-field"><label class="checkbox"><span class="parameter-caption">{{ui("保护原背景")}}</span><input type="checkbox" v-model="p.inpaint.preserveBackground"/></label><ParameterReset :model="p" :defaults="parameterDefaults" path="inpaint.preserveBackground"/></div><div class="resettable-field" ><label class="checkbox"><span class="parameter-caption">{{ui(s.t('反转蒙版','Invert mask'))}}</span><input type="checkbox" v-model="p.inpaint.invertMask"/></label><ParameterReset :model="p" :defaults="parameterDefaults" path="inpaint.invertMask"/></div><div class="resettable-field" ><label><span class="parameter-caption">{{ui(s.t(p.inpaint.preset==='detail'?'重绘强度上限':'重绘强度',p.inpaint.preset==='detail'?'Maximum denoise':'Denoise'))}}</span><input type="range" v-model.number="p.inpaint.denoise" min="0.05" max="1" step="0.05"/><small>{{ui(p.inpaint.denoise)}} · {{ui(s.t('越高变化越大','Higher values change more'))}}</small></label><ParameterReset :model="p" :defaults="parameterDefaults" path="inpaint.denoise"/></div><div class="resettable-field" ><label><span class="parameter-caption">{{ui(s.t(p.inpaint.preset==='detail'?'遮罩扩展上限':'遮罩扩展像素',p.inpaint.preset==='detail'?'Maximum mask expansion':'Mask expansion'))}}</span><input type="number" v-model.number="p.inpaint.growMask" min="0" max="128"/></label><ParameterReset :model="p" :defaults="parameterDefaults" path="inpaint.growMask"/></div><div class="resettable-field" ><label><span class="parameter-caption">{{ui("局部重绘辅助模型")}}</span><select v-model="p.inpaint.controlnet"><option value="">{{ui(s.t('不使用（基础遮罩重绘）','None (masked inpaint)'))}}</option><option v-for="m in s.models.controlnet" :value="m">{{ui(m)}}</option></select></label><ParameterReset :model="p" :defaults="parameterDefaults" path="inpaint.controlnet"/></div><button class="secondary" @click="s.openFolder('controlnet')"><FolderOpen :size="15"/>{{ui(s.t('打开 ControlNet 目录','Open ControlNet folder'))}}</button><div class="resettable-field" ><label><span class="parameter-caption">{{ui(s.t('ControlNet 强度','ControlNet strength'))}}</span><input type="number" v-model.number="p.inpaint.strength" min="0" max="3" step="0.05"/></label><ParameterReset :model="p" :defaults="parameterDefaults" path="inpaint.strength"/></div><div class="resettable-field" ><label><span class="parameter-caption">{{ui(s.t('开始比例','Start percentage'))}}</span><input type="number" v-model.number="p.inpaint.start_percent" min="0" max="1" step="0.05"/></label><ParameterReset :model="p" :defaults="parameterDefaults" path="inpaint.start_percent"/></div><div class="resettable-field" ><label><span class="parameter-caption">{{ui(s.t('结束比例','End percentage'))}}</span><input type="number" v-model.number="p.inpaint.end_percent" min="0" max="1" step="0.05"/></label><ParameterReset :model="p" :defaults="parameterDefaults" path="inpaint.end_percent"/></div><div class="resettable-field" ><label class="checkbox"><span class="parameter-caption">{{ui(s.t('保留已有模型补丁','Preserve model wrapper'))}}</span><input type="checkbox" v-model="p.inpaint.preserve_wrapper"/></label><ParameterReset :model="p" :defaults="parameterDefaults" path="inpaint.preserve_wrapper"/></div></div><p class="info-note">{{ui(s.t('紫色区域会重绘，其余区域保留原图。请选择与当前模型类型匹配的 Anima 重绘 ControlNet。','Only painted areas change. Choose an Anima inpainting ControlNet compatible with the selected model.'))}}</p></div></details>
 </div></section>
 <div class="enhance-heading"><strong>{{ui(s.t('可选后期处理','Optional finishing tools'))}}</strong><span>{{ui(s.t('按需开启，默认折叠；每种模型单独保存参数','Off by default. Settings saved per model.'))}}</span></div><FeatureParams :profile="p" kind="face" :title="ui(s.t('脸部修复','Face restoration'))" :description="s.t('自动识别并细化面部','Detect and refine faces')"/><FeatureParams :profile="p" kind="hand" :title="ui(s.t('手部修复','Hand restoration'))" :description="s.t('修复手指与手部细节','Detect and refine hands')"/><FeatureParams :profile="p" kind="upscale" :title="ui(s.t('图像放大','Upscale image'))" :description="s.t('为漫画导出更清晰的图像','Make a higher resolution image')"/>
 <details v-if="jobHistory.length" class="card job-history"><summary>{{ui(s.t('生成任务记录','Generation history'))}} · {{ui(jobHistory.length)}}<ChevronDown :size="16"/></summary><div v-for="job in [...jobHistory].reverse().slice(0,20)" :key="job.id" class="job-row"><span>{{ui(job.params.type==='expanded'?'Anima 2.9B':'Anima')}}</span><code>{{ui(job.params.seed)}}</code><strong>{{ui(({complete:s.t('已完成','Complete'),error:s.t('失败','Failed'),interrupted:s.t('意外中断','Interrupted'),cancelled:s.t('已取消','Cancelled'),queued:s.t('排队中','Queued'),running:s.t('生成中','Running'),cancelling:s.t('停止中','Stopping')})[job.status])}}</strong><small>{{ui(job.error||job.stage)}}</small><button v-if="['error','interrupted','cancelled'].includes(job.status)" class="text-button" @click="s.action(async()=>{await s.startEngine();await api('jobs/retry',{id:job.id})})">{{ui(s.t('恢复这个任务','Retry task'))}}</button></div></details>
 <footer class="workspace-footer"><button class="quiet" @click="s.openFolder('models')"><FolderOpen :size="15"/>{{ui(s.t('模型文件夹','Models folder'))}}</button><button class="quiet" @click="s.openFolder('output')"><Images :size="15"/>{{ui(s.t('生成结果文件夹','Output folder'))}}</button><span>{{ui(s.t('每张图片均自动保存在 works/output','Every generated image is saved to works/output'))}}</span></footer>
 <input ref="inp" type="file" accept="image/png,image/jpeg,image/webp" class="hidden" @change="importFile"/>
 <div v-if="s.galleryPicker" class="modal-backdrop" @click.self="s.galleryPicker=false"><section class="modal"><div class="modal-dismiss-row"><button class="icon-button" @click="s.galleryPicker=false"><X/></button></div><div class="modal-title"><h2>{{ui(s.t('选择一张图片','Choose an image'))}}</h2></div><div class="picker-grid"><button v-for="item in s.gallery" @click="chooseImage(item)"><img :src="item.url"/><span>{{ui(item.title)}}</span></button></div><p v-if="!s.gallery.length" class="empty">{{ui(s.t('画廊还没有图片，可以先导入本地图片','Your gallery is empty. Import an image first.'))}}</p></section></div>
 <div v-if="zoomed&&displayed" class="modal-backdrop image-modal" v-preview-zoom="{target:'.zoom-content'}" @click.self="zoomed=false"><div class="zoom-content reference-full-image"><img :src="displayed"/><PanelReferenceOverlay v-if="panel&&page&&s.config.previewReference?.enabled!==false" :page="page" :panel="panel" :width="imageSize.w" :height="imageSize.h" :opacity="s.config.previewReference?.opacity??.35"/></div><button class="modal-close" @click="zoomed=false"><X/></button></div>
</div></template>


<style scoped>.generation-preview-header{flex-wrap:wrap;gap:12px}.generation-preview-header>.button-row{flex-wrap:wrap;justify-content:flex-end}.image-drop-overlay{position:absolute;inset:10px;z-index:20;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:12px;border:2px dashed #8065dc;border-radius:12px;background:rgba(247,244,255,.94);color:#6046b8;pointer-events:none}.image-drop-overlay strong{font-size:20px}.image-drop-overlay span{font-size:13px;opacity:.8}</style>
